// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: mbrola:tr1
window.VOICE = {"engine":"mbrola:tr1","gain":1.25,"lines":[{"id":"open-title","say":"Birinci kapı, dördüncü bölüm: veri, bilgi, anlam. Üç basamaklı merdiven.","at":3.8,"dur":7.596,"marks":[0,1.361,2.937,3.78,4.693,5.905]},{"id":"recap-path","say":"Buraya kadar hep fiziği konuştuk: elektriğin nasıl sayıya, sayının nasıl mantığa, mantığın nasıl hesaba dönüştüğünü.","at":12.996,"dur":9.068,"marks":[0,2.688,4.816,6.755]},{"id":"recap-step","say":"Şimdi bir adım geri çekilip, başka bir soru soralım. Bu soru, bundan sonra anlatacağımız her şeyi taşıyacak.","at":23.064,"dur":8.686,"marks":[0,2.287,4.597,5.606]},{"id":"recap-question","say":"Elimizdeki bu sayılar, ne anlama geliyor?","at":32.75,"dur":3.073,"marks":[0,1.897]},{"id":"thermo-alone","say":"Bir termometre, otuz sekiz virgül beş gösteriyor. Bu sayı, tek başına hiçbir şey söylemez.","at":38.223,"dur":7.703,"marks":[0,1.473,4.43,5.431]},{"id":"thermo-room","say":"Bir odanın sıcaklığıysa, boğucu bir yaz gününden bahsediyoruzdur.","at":46.926,"dur":4.725,"marks":[0,2.066]},{"id":"thermo-child","say":"Bir çocuğun ateşiyse, geceyi uykusuz geçireceğiz demektir.","at":52.651,"dur":4.328,"marks":[0,1.853]},{"id":"thermo-oven","say":"Bir fırının sıcaklığıysa, fırın çok soğuk kalmıştır: kek pişirmek için, yüz seksen derece kadar gerekir.","at":57.979,"dur":8.894,"marks":[0,2.187,4.709,6.596]},{"id":"thermo-three","say":"Aynı sayı. Üç farklı dünya.","at":67.873,"dur":2.746,"marks":[0,1.423]},{"id":"thermo-rule","say":"Bu örnek, bilişimin en temel ama en çok atlanan ayrımını gösterir: veri, bilgi ve anlam, asla aynı şey değildir.","at":72.873,"dur":9.13,"marks":[0,0.987,5.184,6.027,7.545]},{"id":"data-def","say":"Basamak bir: veri. Veri, işlenmemiş ham ölçümdür. Tek başına bir yargı taşımaz; yani bize ne yapmamız gerektiğini söylemez.","at":84.203,"dur":11.06,"marks":[0,1.448,2.559,3.402,5.901,8.337]},{"id":"data-examples","say":"Otuz sekiz virgül beş: veri. Sıfır beş yüz otuz iki diye başlayan bir dizi rakam: veri. Bir tarih: veri. Bir renk adı, kırmızı: veri.","at":96.263,"dur":13.433,"marks":[0,2.054,3.165,7.164,8.275,9.438,10.549,11.857,12.983]},{"id":"data-source","say":"Veriyi çoğu zaman bir ölçüm aracı üretir: bir termometre, bir saat, bir kamera. Bazen de form dolduran bir insan. İlk bölümde gördüğümüz gibi, ölçülebilen her şey sayıya çevrilebilir.","at":111.096,"dur":15.122,"marks":[0,3.092,4.565,5.58,7.082,10.023,12.307]},{"id":"data-innocent","say":"Verinin en önemli özelliği, masumiyetidir. Veri, iyi ya da kötü değildir; ama doğru ya da yanlış olabilir.","at":127.218,"dur":8.645,"marks":[0,2.102,3.793,4.636,6.623]},{"id":"data-broken","say":"Bir termometre ya doğru ölçmüştür, ya da bozuktur. Bozuk bir termometre, tamamen sağlıklı bir çocuğa, otuz sekiz virgül beş diyebilir. Veri yanlışsa, üzerine kurulan her şey de yanlış olur.","at":137.463,"dur":15.53,"marks":[0,2.7,4.395,6.261,8.601,11.471,12.948]},{"id":"info-def","say":"Basamak iki: bilgi. Bilgi, verinin bağlamına oturtulmuş hâlidir.","at":155.793,"dur":6.114,"marks":[0,1.497,2.691,3.604]},{"id":"info-context","say":"Bağlam, bir şeyin içinde durduğu çevredir. On iki sayısını düşünün: bir saatin üzerinde, öğle vaktidir. Bir doğum günü pastasının üzerinde, bir yaştır. Bir formanın sırtında, bir oyuncudur. Sayı hiç değişmedi; değişen, çevresiydi.","at":162.907,"dur":21.448,"marks":[0,1.018,3.968,6.186,7.928,9.616,12.304,13.776,15.774,17.387,19.355,20.476]},{"id":"info-questions","say":"Veriye üç sorunun yanıtı eklendiğinde, bilgi doğar. Neyin ölçüsü? Vücut sıcaklığı. Kimin? Ayşe’nin. Ne zaman? Bu sabah.","at":186.155,"dur":12.844,"marks":[0,2.995,4.525,6.263,8.152,9.407,10.797,12.207]},{"id":"info-sentence","say":"Ayşe’nin bu sabahki ateşi, otuz sekiz virgül beş. İşte bu, bilgidir. Artık bir şey söylüyor.","at":200.599,"dur":8.685,"marks":[0,2.432,4.65,5.657,7.019]},{"id":"info-compare","say":"Şimdi karşılaştırma yapılabilir: dün sabah otuz sekiz virgül ikiydi; demek ki yükseliyor. Bir eşikle de kıyaslanabilir: vücut sıcaklığı otuz sekiz dereceye ulaşınca, genellikle ateş sayılır.","at":210.884,"dur":15.729,"marks":[0,2.854,5.791,7.968,10.505,13.966]},{"id":"judge-def","say":"Basamak üç: anlam ve karar. Anlam, bilgiye insanın kendi deneyimi ve yargısı katıldığında ortaya çıkar.","at":228.613,"dur":8.693,"marks":[0,1.4,3.234,4.172]},{"id":"judge-days","say":"Ertesi gün de ateş ölçülüyor. Ayşe’nin ailesi, üç günün ölçümlerini yan yana koyuyor. Deneyimleri ve yargıları devreye girince, şu cümle doğuyor: Ayşe’nin ateşi üçüncü gün de düşmedi; onu doktora götürmeliyiz.","at":238.306,"dur":17.259,"marks":[0,2.656,4.4,7.614,10.719,12.415,15.628]},{"id":"judge-verdict","say":"Bu artık veri değildir; bilgi bile değildir. Bir yargıdır. Ve yargı, her zaman, sorumluluk taşıyan bir insana aittir.","at":257.365,"dur":10.375,"marks":[0,1.992,3.977,5.556,6.625,7.806]},{"id":"ladder-three","say":"Üç basamağı birlikte görelim. Otuz sekiz virgül beş: veri. Ayşe’nin bu sabahki ateşi otuz sekiz virgül beş: bilgi. Onu doktora götürmeliyiz: anlam ve karar.","at":270.14,"dur":14.324,"marks":[0,2.751,4.805,5.916,9.831,11.024,13.15]},{"id":"ladder-machine","say":"Makinelerin asıl işi, bu ilk iki basamaktır. Ölçerler, kaydederler, etiketlerler, karşılaştırırlar; hem de bizden milyonlarca kat hızlı.","at":285.864,"dur":12.39,"marks":[0,1.917,4.142,5.318,6.64,8.053,9.894]},{"id":"ladder-help","say":"Üçüncü basamakta ise makineler yalnızca yardımcı olabilir; asla kesin karar veremez. Akıllı bir termometre, ateş üç gündür yüksek diye uyarabilir; ama Ayşe’yi doktora götürme kararı, ailesinindir.","at":299.254,"dur":15.725,"marks":[0,4.345,6.756,8.675,11.83,14.744]},{"id":"ladder-gray","say":"Yapay zekânın bugün en çok tartışılan o gri bölgesi de, tam olarak burasıdır: makinenin yardımı nerede biter, insanın kararı nerede başlar? Onuncu kapıda, bu konuya uzun uzun döneceğiz.","at":316.579,"dur":14.415,"marks":[0,4.042,5.961,8.415,11.162,12.581]},{"id":"motto-say","say":"Şimdilik akılda kalması gereken tek şey, şu usta sözü: Veri masumdur. Yorum sorumluluktur.","at":333.194,"dur":7.977,"marks":[0,3.341,4.81,6.502]},{"id":"hidden-report","say":"Bir raporda, verilere göre diye başlayan her cümlede, aslında birinin yaptığı gizli bir yorum saklıdır.","at":344.171,"dur":7.512,"marks":[0,1.282,4.313]},{"id":"hidden-four","say":"Hangi verinin toplandığı. Neyin ölçülmediği. Hangi zaman aralığının seçildiği. Sonucun nasıl çizildiği. Bunların hepsi, birer insan kararıdır.","at":352.683,"dur":12.766,"marks":[0,2.396,4.361,7.281,9.697,11.233]},{"id":"hidden-survey","say":"Birincisi, hangi verinin toplandığı. Kütüphane kapısında, çıkan öğrencilere soralım: kitap okumayı seviyor musun? Neredeyse hepsi evet der. Rapor yazılır: öğrencilerin yüzde doksanı okumayı seviyor. Oysa yalnızca kütüphaneye gelenlere sorduk.","at":367.449,"dur":20.793,"marks":[0,1.195,3.59,5.472,7.85,10.504,12.924,14.427,17.952]},{"id":"hidden-missing","say":"İkincisi, neyin ölçülmediği. Bir okul yalnızca sınav notlarını ölçerse, raporda öğrencilerin ne kadar mutlu olduğu hiç görünmez. Ölçülmeyen şey, yok sayılır.","at":390.242,"dur":13.034,"marks":[0,1.179,3.144,6.341,10.524,12.101]},{"id":"hidden-window","say":"Üçüncüsü, zaman aralığı. Bir kasabanın bir yıllık sıcaklık ölçümlerini düşünün. Yalnızca mart ayını seçen biri, hava ısınıyor der. Yalnızca ekim ayını seçen biri, hava soğuyor der. Veri aynı; seçilen zaman aralığı farklı.","at":405.476,"dur":19.404,"marks":[0,1.187,2.813,7.261,9.797,11.701,14.226,16.096,17.306]},{"id":"hidden-axis","say":"Dördüncüsü, çizim. İki sınıfın not ortalaması: yetmiş iki ve yetmiş beş. Grafiğin kenarındaki sayı çizgisine eksen denir. Eksen sıfırdan başlarsa, iki çubuk neredeyse aynı boydadır. Eksen yetmişten başlarsa, biri ötekinin iki buçuk katı görünür. Fark aynı; çizim onu büyütür.","at":426.68,"dur":25.022,"marks":[0,1.288,2.535,4.946,7.55,11.601,13.937,16.923,19.292,22.455,23.775]},{"id":"hidden-myth","say":"Sık duyulan bir söz vardır: rakamlar yalan söylemez. Rakamlar gerçekten yalan söylemez; ama onları seçen ve çizen insan, yanıltabilir.","at":453.702,"dur":11.292,"marks":[0,2.378,4.73,7.693,10.343]},{"id":"hidden-end","say":"Veriler konuşuyor diye bir şey yoktur. Veriyi birileri konuşturur.","at":466.594,"dur":5.061,"marks":[0,3.269]},{"id":"types-why","say":"Bir veriyi bilgisayara emanet edeceksek, ona ne tür bir şey verdiğimizi en baştan söylemek zorundayız. Çünkü makine, beş sayısıyla tırnak içindeki beş yazısı arasındaki o devasa farkı, kendiliğinden anlamaz.","at":474.455,"dur":15.522,"marks":[0,2.949,7.494,8.949,14.059]},{"id":"types-bits","say":"Bellekte ikisi de yalnızca bitlerdir. Beş sayısı, ikilik düzende bir sıfır bir olarak saklanır. Beş yazısı ise, ilk bölümdeki karakter kodlamasına göre, kendi numarasıyla saklanır: elli üç. Peki elli üç sayısı nasıl saklanır? Tıpatıp aynı lambalarla. Lambalar, sayı mı yazı mı olduklarını söylemez; bunu, verinin türü söyler.","at":491.377,"dur":28.284,"marks":[0,3.175,4.519,8.238,9.738,12.982,15.389,16.656,19.864,22.124,23.253,26.058,26.894]},{"id":"types-plus","say":"Farkı en iyi toplama gösterir. Beş artı beş, on eder. Ama iki tane beş yazısını toplamaya kalkarsanız, birçok programlama dili onları yan yana koyar: elli beş yazısı.","at":521.661,"dur":13.628,"marks":[0,2.637,4.012,5.266,8.833,12.424]},{"id":"types-intro","say":"Temel türler, her programlama dilinde şaşırtıcı ölçüde benzerdir.","at":537.289,"dur":4.87,"marks":[0,1.312]},{"id":"types-int","say":"Tam sayı: kırk iki, eksi yedi gibi kesirsiz sayılar. Toplanır, çarpılır.","at":543.159,"dur":7.185,"marks":[0,1.2,2.394,5.311,6.386]},{"id":"types-float","say":"Ondalıklı sayı: otuz sekiz virgül beş gibi kesirli sayılar. Onlar da toplanır, çarpılır.","at":551.344,"dur":7.645,"marks":[0,1.624,5.245,6.845]},{"id":"types-text","say":"Metin: Ayşe gibi bir harf dizisi; tırnak içindeki beş de bir metindir. Birleştirilir, içinde arama yapılır.","at":559.989,"dur":9.381,"marks":[0,1.028,3.369,6.511,7.952]},{"id":"types-bool","say":"Mantıksal: iki durumdan biri; doğru ya da yanlış. İkinci bölümdeki Boole’u hatırlayın. Karar verdirir: ateş otuz sekizden yüksek mi? Doğru.","at":570.37,"dur":13.181,"marks":[0,1.331,3.106,5.006,8.271,9.834,12.651]},{"id":"types-date","say":"Tarih ve saat: zamanda bir nokta, on beş ağustos iki bin yirmi altı gibi. Birbirinden çıkarılır, karşılaştırılır: iki tarih arasında kaç gün var?","at":584.951,"dur":12.27,"marks":[0,1.407,3.078,6.298,8.315,10.054]},{"id":"types-phone","say":"Bu ayrımın neden önemli olduğunu bir örnek anlatır. Telefon numarasını sayı olarak saklarsanız, başındaki sıfır kaybolur. Çünkü sayılarda baştaki sıfırın bir anlamı yoktur: sıfır yedi ile yedi, aynı sayıdır.","at":599.221,"dur":16.172,"marks":[0,3.69,6.988,9.571,13.511,15.24]},{"id":"types-plate","say":"Ankara’nın plaka kodu da öyle: sıfır altı, sayı olarak saklanırsa, altıya döner.","at":616.993,"dur":6.917,"marks":[0,2.636,3.903,5.999]},{"id":"types-rule","say":"Telefon numarası bir sayı değil, bir metindir. Üzerinde hiç toplama yapmayız; yalnızca yazarız ve ararız. Akılda tutulacak küçük bir kural: üzerinde hesap yapmayacaksanız, rakamlardan oluşsa bile, o veri bir metindir.","at":625.51,"dur":17.721,"marks":[0,2.462,4.065,6.591,8.971,11.808,14.309,16.446]},{"id":"struct-list","say":"Şimdi bir öğrenci listesini düşünün. Her satırda ad, soyad, numara ve sınıf var. Her satır, aynı biçimde.","at":645.431,"dur":9.755,"marks":[0,3.157,4.575,5.461,7.584,8.78]},{"id":"struct-name","say":"Buna yapılandırılmış, yani düzenli veri denir. Tabloya kolayca yerleşir; sorgulanır, sıralanır.","at":656.186,"dur":8.355,"marks":[0,1.838,4.025,6.294,7.559]},{"id":"struct-query","say":"Yedi B’deki öğrenciler kimler? Bilgisayar, binlerce satırlık bir tabloda bile, bu soruyu göz açıp kapayıncaya kadar yanıtlar. Beşinci kapının ana konusu, tam olarak budur.","at":666.541,"dur":14.153,"marks":[0,3.032,4.297,7.004,10.708,13.009]},{"id":"messy-notes","say":"Şimdi bir veli toplantısında kâğıda tutulan serbest notları düşünün: birbirini tutmayan uzun cümleler, kenara çizilmiş oklar, yarım kalmış bir liste.","at":682.694,"dur":11.436,"marks":[0,5.161,7.757,9.783]},{"id":"messy-name","say":"Buna yapılandırılmamış, yani düzensiz veri denir. Fotoğraflar, sesler, videolar ve serbest metinler, hep bu karmaşık kümededir. Bir fotoğraf da sayılardan oluşur; ama hiçbir sütun, içinde kimin olduğunu söylemez.","at":695.53,"dur":18.3,"marks":[0,1.967,4.275,5.645,6.717,9.188,11.75,14.592,16.301]},{"id":"messy-ask","say":"Farkı bir soruyla görelim: Ali’nin matematik notu kaç? Tabloda yanıt, bir satır ile bir sütunun kesiştiği yerdedir. Toplantı kâğıdında ise bir cümlenin içinde saklıdır: Ali matematikte biraz zorlanıyor, son sınavda altmış civarı almış galiba. Sıradan bir program, bunu kendiliğinden bulamaz.","at":715.83,"dur":23.414,"marks":[0,2.293,5.008,6.294,9.894,13.797,16.356,19.742,21.611]},{"id":"messy-iceberg","say":"Dünyadaki verinin ezici bir çoğunluğu, işte bu düzensiz kümededir. Tıpkı bir buzdağı gibi: düzenli tablolar görünen ucudur; asıl kütle, suyun altındaki düzensiz yığındır.","at":741.244,"dur":13.485,"marks":[0,2.85,5.331,7.317,9.87,11.123]},{"id":"messy-ai","say":"Ve son yılların en büyük teknolojik atılımı, yapay zekânın o büyük yükselişi, tam da bu düzensiz yığından anlam çıkarabilmesiyle ilgilidir. Ama, sırası gelince.","at":756.329,"dur":12.44,"marks":[0,3.293,5.928,10.573,11.307]},{"id":"sum-ladder","say":"Özetleyelim. Veri, ham ölçümdür. Bilgi, bağlamına oturtulmuş veridir. Anlam ise, bilgiye insanın yargısı katıldığında doğar. Makineler ilk iki basamakta ustadır; üçüncü basamağın sorumluluğu, bizdedir.","at":771.369,"dur":18.414,"marks":[0,1.551,2.394,4.081,4.994,7.638,8.76,12.281,15.289,17.696]},{"id":"close-end","say":"Veri, bilgi, anlam.","at":792.583,"dur":2.307,"marks":[0,0.843,1.756]}],"audio":""};
